// Fetch deal details from CRM when triggered from deal
const input = $input.first().json;

// This would fetch from CRM API
const dealDetails = {
  dealId: input.dealId || input.id,
  customerCompany: input.company || input.account_name,
  customerContact: input.contact_name,
  customerEmail: input.contact_email,
  customerPhone: input.contact_phone || '',
  products: input.products || input.line_items || [],
  dealValue: input.amount || input.value,
  stage: input.stage,
  salesRep: input.owner_name,
  salesRepEmail: input.owner_email
};

return { json: dealDetails };

// Parse and normalize quote request data
const input = $input.first().json;

// Parse products/services JSON if string
let products = [];
try {
  products = typeof input['Products/Services (JSON)'] === 'string' 
    ? JSON.parse(input['Products/Services (JSON)']) 
    : (input['Products/Services (JSON)'] || input.products || []);
} catch (e) {
  products = [];
}

const quoteData = {
  quoteId: `Q-${Date.now()}`,
  createdAt: new Date().toISOString(),

  // Customer info
  customer: {
    company: input['Customer Company Name'] || input.customerCompany || '',
    contactName: input['Customer Contact Name'] || input.customerContact || '',
    email: input['Customer Email'] || input.customerEmail || '',
    phone: input['Customer Phone'] || input.customerPhone || '',
    address: input['Customer Address'] || input.customerAddress || ''
  },

  // Document settings
  documentType: input['Document Type'] || 'Quote',
  validForDays: parseInt(input['Valid For (Days)']) || 30,
  validUntil: new Date(Date.now() + (parseInt(input['Valid For (Days)']) || 30) * 24 * 60 * 60 * 1000).toISOString(),
  paymentTerms: input['Payment Terms'] || 'Net 30',
  currency: input['Currency'] || 'USD',

  // Products
  products: products,
  discount: parseFloat(input['Discount Percentage']) || 0,

  // Delivery options
  includeESign: input['Include E-Signature'] || 'No',
  storageLocation: input['Storage Location'] || 'Google Drive',

  // CRM reference
  crmDealId: input['CRM Deal ID (optional)'] || input.dealId || '',

  // Sales rep
  salesRep: {
    name: input['Sales Rep Name'] || input.salesRep || '',
    email: input['Sales Rep Email'] || input.salesRepEmail || ''
  },

  notes: input['Additional Notes'] || input.notes || ''
};

return { json: quoteData };

// Get pricing data from pricing database/sheet
// In production, this would query a pricing database or Google Sheet

const quoteData = $input.first().json;

// Pricing catalog (would come from database)
const pricingCatalog = {
  // Example pricing tiers
  standardMarkup: 1.0,
  volumeDiscounts: {
    10: 0.05,   // 5% off for 10+ units
    25: 0.10,   // 10% off for 25+ units
    50: 0.15,   // 15% off for 50+ units
    100: 0.20   // 20% off for 100+ units
  },
  taxRate: 0.0,  // Will be calculated based on location
  shippingRates: {
    standard: 0,
    express: 25,
    overnight: 75
  }
};

// Enrich products with current pricing if not provided
const enrichedProducts = quoteData.products.map((product, index) => {
  const quantity = product.quantity || 1;
  const unitPrice = product.unit_price || product.unitPrice || product.price || 0;

  // Calculate volume discount
  let volumeDiscount = 0;
  for (const [threshold, discount] of Object.entries(pricingCatalog.volumeDiscounts)) {
    if (quantity >= parseInt(threshold)) {
      volumeDiscount = discount;
    }
  }

  const subtotal = quantity * unitPrice;
  const discountAmount = subtotal * volumeDiscount;
  const lineTotal = subtotal - discountAmount;

  return {
    lineNumber: index + 1,
    name: product.name || `Item ${index + 1}`,
    description: product.description || '',
    quantity: quantity,
    unitPrice: unitPrice,
    subtotal: subtotal,
    volumeDiscount: volumeDiscount * 100,
    discountAmount: discountAmount,
    lineTotal: lineTotal
  };
});

return {
  json: {
    ...quoteData,
    products: enrichedProducts,
    pricingData: pricingCatalog
  }
};

// Calculate final quote totals
const data = $input.first().json;

// Calculate subtotals
const subtotal = data.products.reduce((sum, p) => sum + p.lineTotal, 0);

// Apply overall discount
const discountPercent = data.discount || 0;
const discountAmount = subtotal * (discountPercent / 100);
const afterDiscount = subtotal - discountAmount;

// Calculate tax (if applicable)
const taxRate = data.pricingData?.taxRate || 0;
const taxAmount = afterDiscount * taxRate;

// Final total
const total = afterDiscount + taxAmount;

// Currency formatting
const currencySymbols = {
  'USD': '$',
  'EUR': '€',
  'GBP': '£',
  'CAD': 'C$',
  'AUD': 'A$'
};
const symbol = currencySymbols[data.currency] || '$';

const formatCurrency = (amount) => {
  return `${symbol}${amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',')}`;
};

const quote = {
  ...data,

  // Calculated totals
  totals: {
    subtotal: subtotal,
    subtotalFormatted: formatCurrency(subtotal),
    discountPercent: discountPercent,
    discountAmount: discountAmount,
    discountFormatted: formatCurrency(discountAmount),
    afterDiscount: afterDiscount,
    afterDiscountFormatted: formatCurrency(afterDiscount),
    taxRate: taxRate * 100,
    taxAmount: taxAmount,
    taxFormatted: formatCurrency(taxAmount),
    total: total,
    totalFormatted: formatCurrency(total)
  },

  // Format products for display
  formattedProducts: data.products.map(p => ({
    ...p,
    unitPriceFormatted: formatCurrency(p.unitPrice),
    subtotalFormatted: formatCurrency(p.subtotal),
    lineTotalFormatted: formatCurrency(p.lineTotal)
  }))
};

return { json: quote };

