// Parse AI response and generate PDF content
const data = $input.first().json;

// Parse AI generated content
let aiContent = {
  executiveSummary: 'We are pleased to present this proposal for your consideration.',
  coverLetter: 'Thank you for the opportunity to work with your organization.',
  termsAndConditions: [
    'Payment due according to agreed terms',
    'Prices valid for the period specified',
    'Subject to our standard terms of service'
  ],
  closingStatement: 'We look forward to working with you.'
};

try {
  const aiOutput = data.output || data.text || '';
  const jsonMatch = aiOutput.match(/```json\n?([\s\S]*?)\n?```/) || aiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiContent = { ...aiContent, ...JSON.parse(jsonMatch[1] || jsonMatch[0]) };
  }
} catch (e) {
  console.log('Using default AI content');
}

// Generate HTML for PDF
const html = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; margin: 40px; color: #333; }
    .header { border-bottom: 3px solid #2c5aa0; padding-bottom: 20px; margin-bottom: 30px; }
    .logo { font-size: 28px; font-weight: bold; color: #2c5aa0; }
    .document-title { font-size: 24px; color: #666; margin-top: 10px; }
    .quote-info { background: #f5f5f5; padding: 20px; border-radius: 5px; margin-bottom: 30px; }
    .quote-info table { width: 100%; }
    .quote-info td { padding: 5px 0; }
    .quote-info .label { font-weight: bold; width: 150px; }
    .summary { margin-bottom: 30px; font-style: italic; color: #555; }
    table.products { width: 100%; border-collapse: collapse; margin-bottom: 30px; }
    table.products th { background: #2c5aa0; color: white; padding: 12px; text-align: left; }
    table.products td { padding: 12px; border-bottom: 1px solid #ddd; }
    table.products tr:nth-child(even) { background: #f9f9f9; }
    .totals { text-align: right; margin-bottom: 30px; }
    .totals table { margin-left: auto; }
    .totals td { padding: 8px 15px; }
    .totals .total-row { font-size: 18px; font-weight: bold; background: #2c5aa0; color: white; }
    .terms { background: #f9f9f9; padding: 20px; border-radius: 5px; margin-bottom: 30px; }
    .terms h3 { margin-top: 0; color: #2c5aa0; }
    .terms ul { margin: 0; padding-left: 20px; }
    .closing { margin-top: 40px; }
    .signature-block { margin-top: 60px; display: flex; justify-content: space-between; }
    .signature { width: 45%; }
    .signature-line { border-top: 1px solid #333; margin-top: 50px; padding-top: 10px; }
    .footer { margin-top: 60px; text-align: center; color: #999; font-size: 12px; }
  </style>
</head>
<body>
  <div class="header">
    <div class="logo">Your Company Name</div>
    <div class="document-title">${data.documentType} #${data.quoteId}</div>
  </div>

  <div class="quote-info">
    <table>
      <tr>
        <td class="label">Prepared For:</td>
        <td>${data.customer.company}<br>${data.customer.contactName}<br>${data.customer.email}</td>
        <td class="label">Date:</td>
        <td>${new Date(data.createdAt).toLocaleDateString()}</td>
      </tr>
      <tr>
        <td class="label">Valid Until:</td>
        <td>${new Date(data.validUntil).toLocaleDateString()}</td>
        <td class="label">Prepared By:</td>
        <td>${data.salesRep.name}<br>${data.salesRep.email}</td>
      </tr>
      <tr>
        <td class="label">Payment Terms:</td>
        <td>${data.paymentTerms}</td>
        <td></td>
        <td></td>
      </tr>
    </table>
  </div>

  <div class="summary">
    <p>${aiContent.executiveSummary}</p>
  </div>

  <h3>Products & Services</h3>
  <table class="products">
    <thead>
      <tr>
        <th>#</th>
        <th>Description</th>
        <th>Qty</th>
        <th>Unit Price</th>
        <th>Total</th>
      </tr>
    </thead>
    <tbody>
      ${data.formattedProducts.map(p => `
        <tr>
          <td>${p.lineNumber}</td>
          <td><strong>${p.name}</strong><br><small>${p.description || ''}</small></td>
          <td>${p.quantity}</td>
          <td>${p.unitPriceFormatted}</td>
          <td>${p.lineTotalFormatted}</td>
        </tr>
      `).join('')}
    </tbody>
  </table>

  <div class="totals">
    <table>
      <tr>
        <td>Subtotal:</td>
        <td>${data.totals.subtotalFormatted}</td>
      </tr>
      ${data.totals.discountPercent > 0 ? `
      <tr>
        <td>Discount (${data.totals.discountPercent}%):</td>
        <td>-${data.totals.discountFormatted}</td>
      </tr>
      ` : ''}
      ${data.totals.taxRate > 0 ? `
      <tr>
        <td>Tax (${data.totals.taxRate}%):</td>
        <td>${data.totals.taxFormatted}</td>
      </tr>
      ` : ''}
      <tr class="total-row">
        <td>Total (${data.currency}):</td>
        <td>${data.totals.totalFormatted}</td>
      </tr>
    </table>
  </div>

  <div class="terms">
    <h3>Terms & Conditions</h3>
    <ul>
      ${aiContent.termsAndConditions.map(t => `<li>${t}</li>`).join('')}
    </ul>
  </div>

  <div class="closing">
    <p>${aiContent.closingStatement}</p>
  </div>

  <div class="signature-block">
    <div class="signature">
      <div class="signature-line">
        <strong>Customer Signature</strong><br>
        ${data.customer.contactName}<br>
        Date: _______________
      </div>
    </div>
    <div class="signature">
      <div class="signature-line">
        <strong>Company Representative</strong><br>
        ${data.salesRep.name}<br>
        Date: ${new Date().toLocaleDateString()}
      </div>
    </div>
  </div>

  <div class="footer">
    <p>Thank you for your business!</p>
    <p>Questions? Contact ${data.salesRep.email}</p>
  </div>
</body>
</html>
`;

return {
  json: {
    ...data,
    aiContent,
    pdfHtml: html,
    fileName: `${data.documentType.replace(/\s+/g, '_')}_${data.quoteId}.pdf`
  }
};

// Create e-signature request if enabled
const data = $input.first().json;

const eSignProvider = data.includeESign;
let eSignRequest = null;

if (eSignProvider && eSignProvider !== 'No') {
  eSignRequest = {
    provider: eSignProvider.replace('Yes - ', ''),
    documentName: data.fileName,
    signers: [
      {
        name: data.customer.contactName,
        email: data.customer.email,
        role: 'Customer'
      }
    ],
    ccRecipients: [
      {
        name: data.salesRep.name,
        email: data.salesRep.email
      }
    ],
    subject: `Please sign: ${data.documentType} #${data.quoteId}`,
    message: `Please review and sign the attached ${data.documentType.toLowerCase()} from ${data.salesRep.name}.`,
    expirationDays: data.validForDays
  };
}

return {
  json: {
    ...data,
    eSignRequest,
    eSignEnabled: eSignProvider !== 'No'
  }
};

// Update CRM deal with quote information
const data = $input.first().json;

const crmUpdate = {
  dealId: data.crmDealId,
  updates: {
    quoteId: data.quoteId,
    quoteAmount: data.totals.total,
    quoteCurrency: data.currency,
    quoteDate: data.createdAt,
    quoteValidUntil: data.validUntil,
    quoteStatus: 'Sent',
    lastActivity: new Date().toISOString(),
    lastActivityType: 'Quote Sent'
  }
};

return {
  json: {
    ...data,
    crmUpdate
  }
};

